import sys
from collections import defaultdict

def max_operations(N, a):
    dp = defaultdict(lambda: float('inf'))
    dp[0] = 0

    for num in a:
        if num % 3 == 0:
            dp[num] = min(dp[num], dp[num // 3])
        else:
            dp[num] = min(dp[num], dp[num * 3])

        if num % 2 == 0:
            dp[num] = min(dp[num], dp[num // 2])

    return sum(dp[num] for num in a)

